          resolve({
            success: false,
            output: "",
            error: typeof msg.error === "string" ? msg.error : JSON.stringify(msg.error),
          });
        } else {
          const outStr = typeof msg.result === "string"
            ? msg.result
            : JSON.stringify(msg.result, null, 2);
          resolve({
            success: true,
            output: outStr,
          });
        }
      }
    } catch {
      // Non-JSON output (e.g. cargo build notes)
    }
  }
