  if (code && CAPACITY_CODES.has(code)) return { condition: "CAPACITY_REJECTED", execution: "NOT_EXECUTED" };
  if (status === 402 || (code && QUOTA_CODES.has(code)) || (hints.errorType && QUOTA_CODES.has(hints.errorType))) {
